// Procedural map rendering: parallax backgrounds + themed platforms.
(function () {
  const { MAPS } = (typeof SHARED !== 'undefined' ? SHARED : require('./shared.js'));

  function rng(seed) { const s = Math.sin(seed * 127.1) * 43758.5453; return s - Math.floor(s); }

  // precomputed scenery
  const clouds = [];
  for (let i = 0; i < 12; i++) {
    clouds.push({ x: rng(i) * 2400 - 1200, y: rng(i + 50) * 500 - 420, s: 0.6 + rng(i + 99) * 1.2, v: 8 + rng(i + 7) * 18 });
  }
  const stars = [];
  for (let i = 0; i < 90; i++) {
    stars.push({ x: rng(i + 200) * 2400 - 1200, y: rng(i + 300) * 800 - 700, r: 0.5 + rng(i + 400) * 1.8, tw: rng(i + 500) * 6 });
  }
  const embers = [];
  for (let i = 0; i < 40; i++) {
    embers.push({ x: rng(i + 600) * 2200 - 1100, y: rng(i + 700) * 900 - 300, v: 30 + rng(i + 800) * 60, ph: rng(i + 900) * 10 });
  }

  function drawCloud(ctx, x, y, s, alpha) {
    ctx.fillStyle = `rgba(255,255,255,${alpha})`;
    ctx.beginPath();
    ctx.arc(x, y, 28 * s, 0, Math.PI * 2);
    ctx.arc(x + 30 * s, y - 10 * s, 22 * s, 0, Math.PI * 2);
    ctx.arc(x + 58 * s, y, 26 * s, 0, Math.PI * 2);
    ctx.arc(x + 28 * s, y + 10 * s, 24 * s, 0, Math.PI * 2);
    ctx.fill();
  }

  // ---- backgrounds (drawn in screen space; px/py are parallax helpers) ----

  function bgSkylands(ctx, W, H, cam, t) {
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#4a90d9'); g.addColorStop(0.55, '#8ec8ef'); g.addColorStop(1, '#d8f0fa');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    // sun
    const sg = ctx.createRadialGradient(W * 0.78, H * 0.18, 10, W * 0.78, H * 0.18, 160);
    sg.addColorStop(0, 'rgba(255,250,210,0.95)'); sg.addColorStop(0.3, 'rgba(255,240,180,0.45)'); sg.addColorStop(1, 'rgba(255,240,180,0)');
    ctx.fillStyle = sg; ctx.fillRect(W * 0.78 - 170, H * 0.18 - 170, 340, 340);
    // distant islands (parallax 0.25)
    const px = -cam.x * 0.25, py = -cam.y * 0.25;
    ctx.fillStyle = 'rgba(90,130,170,0.45)';
    for (let i = 0; i < 4; i++) {
      const ix = W / 2 + px + (i - 1.5) * 480 + rng(i + 31) * 120;
      const iy = H * 0.55 + py + rng(i + 77) * 140;
      ctx.beginPath();
      ctx.ellipse(ix, iy, 90 + rng(i) * 60, 26, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(ix - 60, iy + 8); ctx.lineTo(ix, iy + 70 + rng(i + 3) * 30); ctx.lineTo(ix + 60, iy + 8);
      ctx.closePath(); ctx.fill();
    }
    // clouds (parallax 0.4, drifting)
    for (const c of clouds) {
      let cx = W / 2 + (c.x + t * c.v) % 2400 - 1200 - cam.x * 0.4;
      const cy = H / 2 + c.y * 0.8 - cam.y * 0.4;
      drawCloud(ctx, cx, cy, c.s, 0.75);
    }
  }

  function bgFlatline(ctx, W, H, cam, t) {
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#070716'); g.addColorStop(0.6, '#1b0b38'); g.addColorStop(1, '#3d1155');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    // stars
    for (const s of stars) {
      const a = 0.4 + 0.6 * Math.abs(Math.sin(t * 0.8 + s.tw));
      ctx.fillStyle = `rgba(220,225,255,${a})`;
      ctx.beginPath();
      ctx.arc(W / 2 + s.x - cam.x * 0.1, H / 2 + s.y * 0.6 - cam.y * 0.1, s.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // synthwave sun
    const sx = W / 2 - cam.x * 0.15, sy = H * 0.42 - cam.y * 0.15;
    const sg = ctx.createLinearGradient(0, sy - 110, 0, sy + 110);
    sg.addColorStop(0, '#ffd23e'); sg.addColorStop(1, '#ff3e8a');
    ctx.fillStyle = sg;
    ctx.beginPath(); ctx.arc(sx, sy, 110, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#1b0b38';
    for (let i = 0; i < 5; i++) ctx.fillRect(sx - 115, sy + 10 + i * 22, 230, 6 + i * 2);
    // grid floor
    const horizon = H * 0.62 - cam.y * 0.2;
    ctx.strokeStyle = 'rgba(0,229,255,0.35)';
    ctx.lineWidth = 1.5;
    for (let i = 0; i < 14; i++) {
      const yy = horizon + Math.pow(i / 13, 2.2) * (H - horizon);
      ctx.beginPath(); ctx.moveTo(0, yy); ctx.lineTo(W, yy); ctx.stroke();
    }
    const vp = W / 2 - cam.x * 0.2;
    for (let i = -10; i <= 10; i++) {
      ctx.beginPath(); ctx.moveTo(vp + i * 30, horizon); ctx.lineTo(vp + i * 260, H); ctx.stroke();
    }
  }

  function bgVolcano(ctx, W, H, cam, t) {
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#1c0808'); g.addColorStop(0.55, '#4a1410'); g.addColorStop(1, '#8a2a12');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    // distant volcanoes (parallax 0.25)
    const px = -cam.x * 0.25, py = -cam.y * 0.25;
    for (let i = 0; i < 3; i++) {
      const vx = W / 2 + px + (i - 1) * 620 + rng(i + 11) * 100;
      const vy = H * 0.78 + py;
      ctx.fillStyle = '#2a0d0a';
      ctx.beginPath();
      ctx.moveTo(vx - 260, vy); ctx.lineTo(vx - 28, vy - 300 - rng(i) * 80); ctx.lineTo(vx + 28, vy - 300 - rng(i) * 80); ctx.lineTo(vx + 260, vy);
      ctx.closePath(); ctx.fill();
      const glow = 0.5 + 0.4 * Math.sin(t * 2 + i * 2);
      ctx.fillStyle = `rgba(255,120,30,${glow})`;
      ctx.beginPath();
      ctx.ellipse(vx, vy - 298 - rng(i) * 80, 30, 9, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    // lava glow at the bottom
    const lg = ctx.createLinearGradient(0, H * 0.75, 0, H);
    lg.addColorStop(0, 'rgba(255,90,0,0)'); lg.addColorStop(1, `rgba(255,140,20,${0.55 + 0.15 * Math.sin(t * 3)})`);
    ctx.fillStyle = lg; ctx.fillRect(0, H * 0.75, W, H * 0.25);
    // rising embers
    for (const e of embers) {
      const ey = H - ((e.y + t * e.v) % (H + 100));
      const ex = W / 2 + e.x * (W / 2200) - cam.x * 0.4 + Math.sin(t * 2 + e.ph) * 18;
      ctx.fillStyle = `rgba(255,${150 + Math.floor(rng(e.ph) * 80)},40,${0.5 + 0.5 * Math.sin(t * 4 + e.ph)})`;
      ctx.beginPath(); ctx.arc(ex, ey, 2.2, 0, Math.PI * 2); ctx.fill();
    }
  }

  const BACKGROUNDS = { skylands: bgSkylands, flatline: bgFlatline, volcano: bgVolcano };

  // ---- platforms (drawn in world space via w2s transform) ----

  function platSkylands(ctx, pl) {
    if (pl.main) {
      ctx.fillStyle = '#7a5a3a';                              // dirt body
      ctx.beginPath();
      ctx.moveTo(pl.x, pl.y);
      ctx.lineTo(pl.x + pl.w, pl.y);
      ctx.lineTo(pl.x + pl.w - 90, pl.y + 130);
      ctx.lineTo(pl.x + pl.w / 2, pl.y + 190);
      ctx.lineTo(pl.x + 90, pl.y + 130);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#5d8a3c';                              // grass
      ctx.fillRect(pl.x, pl.y, pl.w, 16);
      ctx.fillStyle = '#79ad4e';
      ctx.fillRect(pl.x, pl.y, pl.w, 7);
    } else {
      ctx.fillStyle = '#8d8d99';
      ctx.fillRect(pl.x, pl.y, pl.w, pl.h);
      ctx.fillStyle = '#79ad4e';
      ctx.fillRect(pl.x, pl.y, pl.w, 6);
      ctx.fillStyle = 'rgba(0,0,0,0.2)';
      ctx.fillRect(pl.x, pl.y + pl.h - 5, pl.w, 5);
    }
  }

  function platFlatline(ctx, pl, t) {
    ctx.fillStyle = '#11112a';
    ctx.fillRect(pl.x, pl.y, pl.w, pl.h + (pl.main ? 60 : 0));
    ctx.shadowColor = '#00e5ff'; ctx.shadowBlur = 16;
    ctx.strokeStyle = '#00e5ff'; ctx.lineWidth = 3;
    ctx.strokeRect(pl.x, pl.y, pl.w, pl.h + (pl.main ? 60 : 0));
    ctx.shadowBlur = 0;
    ctx.strokeStyle = `rgba(255,62,138,${0.5 + 0.3 * Math.sin(t * 3)})`;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(pl.x + 8, pl.y + 8); ctx.lineTo(pl.x + pl.w - 8, pl.y + 8); ctx.stroke();
  }

  function platVolcano(ctx, pl, t) {
    if (pl.main) {
      ctx.fillStyle = '#241312';
      ctx.beginPath();
      ctx.moveTo(pl.x, pl.y);
      ctx.lineTo(pl.x + pl.w, pl.y);
      ctx.lineTo(pl.x + pl.w - 60, pl.y + 150);
      ctx.lineTo(pl.x + 60, pl.y + 150);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#3d2320';
      ctx.fillRect(pl.x, pl.y, pl.w, 14);
      // glowing cracks
      ctx.strokeStyle = `rgba(255,120,20,${0.6 + 0.3 * Math.sin(t * 4)})`;
      ctx.lineWidth = 3;
      for (let i = 0; i < 3; i++) {
        const cx = pl.x + pl.w * (0.25 + i * 0.25);
        ctx.beginPath();
        ctx.moveTo(cx, pl.y + 16);
        ctx.lineTo(cx - 14, pl.y + 55);
        ctx.lineTo(cx + 8, pl.y + 90);
        ctx.stroke();
      }
    } else {
      ctx.fillStyle = '#1a0f14';
      ctx.fillRect(pl.x, pl.y, pl.w, pl.h);
      ctx.strokeStyle = 'rgba(255,120,20,0.7)';
      ctx.lineWidth = 2;
      ctx.strokeRect(pl.x, pl.y, pl.w, pl.h);
    }
  }

  const PLATFORM_STYLES = { skylands: platSkylands, flatline: platFlatline, volcano: platVolcano };

  function drawBackground(ctx, mapKey, W, H, cam, t) {
    (BACKGROUNDS[mapKey] || bgSkylands)(ctx, W, H, cam, t);
  }

  function drawPlatforms(ctx, mapKey, t) {
    const map = MAPS[mapKey];
    const style = PLATFORM_STYLES[mapKey] || platSkylands;
    for (const pl of map.platforms) style(ctx, pl, t);
  }

  // small preview for the map-select screen
  function drawPreview(canvas, mapKey) {
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    drawBackground(ctx, mapKey, W, H, { x: 0, y: 0 }, 2.5);
    const map = MAPS[mapKey];
    const scale = W / 2400;
    ctx.save();
    ctx.translate(W / 2, H * 0.42);
    ctx.scale(scale, scale);
    drawPlatforms(ctx, mapKey, 2.5);
    ctx.restore();
  }

  const api = { drawBackground, drawPlatforms, drawPreview };
  if (typeof module === 'object' && module.exports) module.exports = api;
  else window.MAPRENDER = api;
})();
